"""Independent retained-probe arithmetic and append-only diagnostic note."""
import pathlib,sys
R=pathlib.Path(__file__).resolve().parents[1];sys.path.insert(0,str(R.parent/'cycle29/scripts'));import runtime_profile
import numpy as np,json,hashlib,datetime
def sha(p):return hashlib.sha256(pathlib.Path(p).read_bytes()).hexdigest()
def read(p):return json.loads(pathlib.Path(p).read_text(encoding='utf-8'))
def main():
 assert read(R/'outputs/report_supervisor_v1.json')['status']=='REPORTS_COMPLETE_VISUAL_QA_PENDING';out=R/'outputs/train_val_diagnostics_v1';d=read(out/'diagnostics.json');assert not (out/'verification.json').exists();errors=[]
 for row in d['records']:
  p=out/(row['model']+'.npz');assert sha(p)==row['raw_sha256'];raw=np.load(p);X=np.column_stack([raw['train_state'],np.ones(len(raw['train_state']))]);Z=raw['train_true_z'];augx=np.vstack([X,np.eye(5)*.001]);augz=np.vstack([Z,np.zeros((5,4))]);coef=np.linalg.lstsq(augx,augz,rcond=None)[0];valx=np.column_stack([raw['val_state'],np.ones(len(raw['val_state']))]);prediction=valx@coef;truth=raw['val_true_z'];mse=float(np.mean((prediction-truth)**2));r2=float(1-np.sum((prediction-truth)**2)/np.sum((truth-truth.mean(0))**2));future_mse=float(np.mean((raw['val_predicted_future_z']-raw['val_true_future_z'])**2));errors.append(max(abs(mse-row['val_state_linear_probe_mse']),abs(r2-row['val_state_linear_probe_r2']),abs(future_mse-row['val_future_state_probe_mse'])));assert errors[-1]<1e-7,(row['model'],errors[-1])
 val=np.load(R/'data/val.npz');zero_recon=float(np.mean([np.mean(x[:,:8]**2) for x in val.values()]));lines=['# C46 TRAIN/VAL failure-attribution addendum','',f"Generator replay on every retained TRAIN/VAL trajectory: max observation mismatch{d['generator_replay_max_abs']:.3g}. Independent augmented-SVD ridge refit and raw-score arithmetic max discrepancy{max(errors):.3g}. The true states and probe labels are auditor-only; no forecasting model or selection receives them.",'','| Model | VAL current-state affine probe R2 | VAL future-state probe MSE | VAL q-mean decoder reconstruction MSE |','|---|---:|---:|---:|']
 for row in d['records']:
  rec='not comparable' if row['val_instantaneous_qmean_decoder_reconstruction_mse'] is None else f"{row['val_instantaneous_qmean_decoder_reconstruction_mse']:.6f}";lines.append(f"| {row['model']} | {row['val_state_linear_probe_r2']:.6f} | {row['val_future_state_probe_mse']:.6f} | {rec} |")
 lines+=['',f'Zero decoder prediction on these same normalized VAL history frames has MSE{zero_recon:.6f}. Decoder values above are the output at the auxiliary mean, not an expectation of a nonlinear decoder or a likelihood estimate.','', 'The cheap aligned Gaussian model retains substantially more linearly decodable current-state information in this fixture. This is a concrete warning against attributing the native neural deficit to missing composition or proposing a new architecture from its rollout error. Optimization, objective/inference restrictions and nonlinear latent gauge effects remain competing explanations. The affine probe alone is not a universal test of information loss or physical identifiability.','', 'Future-state MSE includes irreducible process randomness. These probes are not new forecasting methods and are not an oracle conditional-reference bound. No sealed EVAL values were used here, and no fit, checkpoint selection or hyperparameter was changed. A claimed new mechanism would still require a new hypothesis and independent held-out evidence.']
 note='\n'.join(lines)+'\n';(R/'DIAGNOSTIC_INTERPRETATION.md').write_text(note,encoding='utf-8');tag='<!-- c46-privileged-train-val-diagnostics -->';archive=out/'report_pre_addendum';archive.mkdir(exist_ok=True);receipts=[]
 for name in ['experimental_results.md','negative_evidence.md','hypothesis_space.md','final_research_direction.md','SCIENTIFIC_DECISION.md']:
  p=R/name;old=p.read_bytes();assert tag.encode() not in old;(archive/name).write_bytes(old);addition='\n\n'+tag+'\nTRAIN/VAL-only known-state probes and their independent arithmetic verification are available in [DIAGNOSTIC_INTERPRETATION.md](DIAGNOSTIC_INTERPRETATION.md). These explain why the neural deficit is not evidence of a new mechanism gap; no EVAL tuning or training change occurred.\n';assert p.read_bytes()==old;p.write_bytes(old+addition.encode());receipts.append({'path':name,'before':hashlib.sha256(old).hexdigest(),'after':sha(p)})
 result={'status':'PASS_TRAIN_VAL_DIAGNOSTICS_ONLY','utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'groups':len(d['records']),'max_independent_probe_error':max(errors),'zero_decoder_val_history_MSE':zero_recon,'note_sha256':sha(R/'DIAGNOSTIC_INTERPRETATION.md'),'source_sha256':sha(__file__),'appended_reports':receipts};(out/'verification.json').write_text(json.dumps(result,indent=2),encoding='utf-8');(R/'REPORT_ADDENDUM_MANIFEST.json').write_text(json.dumps({'supersedes_report_hashes_only_in':receipts,'diagnostic_verification_sha256':sha(out/'verification.json'),'not_a_research_goal_completion':True},indent=2),encoding='utf-8');print(json.dumps(result),flush=True)
if __name__=='__main__':main()
